      --cal-accent-2: #9b7cff;
      --cal-today: #ff5c8a;
      --cal-warn: #ffb04d;
      --cal-wash: rgba(255, 106, 213, 0.10);
      --cal-ripple: rgba(255, 106, 213, 0.30);
      --cal-outside: 0.32;
      --cal-chrome: linear-gradient(var(--cal-ink), var(--cal-ink));
      --cal-gloss: rgba(255, 255, 255, 0.14);
    }
  }

  * { box-sizing: border-box; }

  html, body { margin: 0; padding: 0; }

  body {
    min-height: 100vh;
    min-height: 100dvh;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    padding: 24px 16px;
    background: linear-gradient(180deg, var(--cal-page) 0%, var(--cal-page-3) 48%, var(--cal-page-2) 100%);
    background-attachment: fixed;
    font-family: 'Nunito', -apple-system, BlinkMacSystemFont, 'Segoe UI',
      'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', system-ui, sans-serif;
    -webkit-font-smoothing: antialiased;
  }

  /* 主体：磨砂泡泡卡（光泽边+内高光） */
  .cal {
    position: relative;
    width: 100%;
    max-width: 420px;
    padding: 20px 16px 18px;
    border: 1px solid var(--cal-gloss);
    border-radius: var(--cal-radius);
    background: linear-gradient(180deg, var(--cal-card) 0%, var(--cal-card-2) 100%);
    backdrop-filter: blur(14px);
    box-shadow: 0 18px 44px rgba(88, 40, 140, 0.2), inset 0 1px 0 var(--cal-gloss), inset 0 0 44px rgba(255, 255, 255, 0.3);
    color: var(--cal-ink);
  }

  /* 顶部：控件行 + 大标题 + 选中日说明 */
  .cal-head { position: relative; padding: 2px 6px 0; }

  /* Y2K 装饰：只落标题区；不占高度不挡点击 */
  .cal-deco { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
  .cal-deco i {
    position: absolute;
    left: 2%;
    top: 3px;
    width: 22px;
    height: 22px;
    background: linear-gradient(140deg, var(--cal-accent), var(--cal-accent-2));
    clip-path: polygon(50% 0, 61% 39%, 100% 50%, 61% 61%, 50% 100%, 39% 61%, 0 50%, 39% 39%);
    animation: cal-float 7s ease-in-out infinite;
  }
  .cal-deco i:nth-child(2) { left: auto; right: 24%; top: 52px; width: 13px; height: 13px; animation-delay: -2.4s; }
  .cal-fly {
    position: absolute;
    right: 6%;
    top: 44px;
    width: 26px;
    height: 26px;
    fill: var(--cal-accent);
    animation: cal-float 7s ease-in-out infinite -1.2s;
  }
  @keyframes cal-float {
    0%, 100% { transform: translateY(0) rotate(0deg); }
    50% { transform: translateY(-9px) rotate(14deg); }
  }

  .cal-bar {
    display: flex;
    align-items: center;
    gap: 6px;
    min-height: 30px;
  }
  .cal-bar-spacer { flex: 1 1 auto; }

  .cal-btn {
    appearance: none;
    border: 0;
    background: transparent;
    color: var(--cal-accent);
    font: inherit;
    font-size: 15px;
    line-height: 1;
    padding: 7px 10px;
    border-radius: 999px;
    cursor: pointer;
    transition: background-color 0.15s ease;
  }
  .cal-btn:hover { background: var(--cal-hover); }
  .cal-btn:focus-visible { outline: 2px solid var(--cal-accent); outline-offset: 1px; }
  .cal-btn[hidden] { display: none; }

  .cal-arrow {
    width: 30px;
    height: 30px;
    padding: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--cal-ink-2);
  }
  .cal-arrow:hover { color: var(--cal-ink); }
  .cal-arrow svg { width: 16px; height: 16px; display: block; }

  /* 大标题：全页唯一高光点——铬面 + 3D 边 */
  .cal-title {
    display: inline-block;
    margin: 14px 0 0;
    font-family: 'Fredoka', 'Nunito', -apple-system, system-ui, sans-serif;
    font-size: 34px;
    line-height: 1.15;
    font-weight: 700;
    letter-spacing: -0.01em;
    background-image: var(--cal-chrome);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    filter: drop-shadow(0 2px 1px rgba(88, 40, 140, 0.30));
  }
  .cal-subtitle {
    margin: 6px 0 0;
    font-size: 13px;
    line-height: 1.35;
    color: var(--cal-ink-2);
    font-variant-numeric: tabular-nums;
  }

  /* 星期表头 */
  .cal-weekdays {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    margin-top: 18px;
    padding-bottom: 4px;
  }
  .cal-weekday {
    text-align: center;
    font-size: 12px;
    font-weight: 500;
    color: var(--cal-ink-2);
    letter-spacing: 0.02em;
  }

  /* 日期网格：7 列 × 6 行，周一首列 */
  .cal-grid {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    margin-top: 2px;
    user-select: none;
    -webkit-user-select: none;
    touch-action: pan-y;           /* 纵向留给滚动，横向留给切月手势 */
    cursor: default;
  }
  .cal-grid:focus { outline: none; }
  .cal-grid:focus-visible { outline: 2px solid var(--cal-accent); outline-offset: 4px; border-radius: 12px; }
  .cal-grid.is-dragging { cursor: grabbing; }

  .cal-day {
    appearance: none;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    padding: 0;
    height: 46px;
    display: flex;
    flex-direction: column;        /* 数字圆在上、任务点在下 */
    align-items: center;
    justify-content: center;
    gap: 3px;
    cursor: pointer;
  }
  .cal-day-num {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;       /* 日期数字居中 */
    font-size: 17px;
    font-variant-numeric: tabular-nums;
    transition: background-color 0.14s ease, color 0.14s ease;
  }
  /* 密度点：一天最多三枚，按紧急度取前三 */
  .cal-dots {
    height: 5px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 3px;
  }
  .cal-dot {
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--cal-accent);
    opacity: 0.75;
  }
  .cal-dot.is-overdue { background: var(--cal-today); opacity: 1; }
  .cal-dot.is-priority { background: var(--cal-warn); opacity: 1; }
  .cal-dot.is-done { background: var(--cal-ink); opacity: 0.22; }
  /* 日记字数点（Calendar）：中性灰，排在任务点前 */
  .cal-dot.is-note { background: var(--cal-ink); opacity: 0.42; }
  .cal-day:hover .cal-day-num { background: var(--cal-hover); }
  .cal-day:focus-visible { outline: none; }
  .cal-day:focus-visible .cal-day-num { outline: 2px solid var(--cal-accent); outline-offset: 1px; }

  .cal-day.is-outside { opacity: var(--cal-outside); }          /* 非当月日期弱化 */
  .cal-day.is-today .cal-day-num { color: var(--cal-today); font-weight: 600; }
  .cal-day.is-selected .cal-day-num {                            /* 选中态：泡泡渐变填充 */
    background-image: linear-gradient(140deg, var(--cal-accent) 0%, var(--cal-accent-2) 100%);
    color: var(--cal-accent-ink);
    font-weight: 600;
  }
  .cal-day.is-selected:hover .cal-day-num {
    background-image: linear-gradient(140deg, var(--cal-accent) 0%, var(--cal-accent-2) 100%);
  }

  /* 切月动效：一次轻推；跟手走即时位移 */
  .cal-grid.is-anim { animation: cal-push-in 0.18s ease-out; }
  .cal-grid.is-anim-next { animation-name: cal-push-in-next; }
  .cal-grid.is-anim-prev { animation-name: cal-push-in-prev; }
  .cal-grid.is-dragging { transition: none; }
  @keyframes cal-push-in-next {
    from { transform: translateX(14px); opacity: 0.4; }
    to   { transform: translateX(0);    opacity: 1; }
  }
  @keyframes cal-push-in-prev {
    from { transform: translateX(-14px); opacity: 0.4; }
    to   { transform: translateX(0);     opacity: 1; }
  }
  @media (prefers-reduced-motion: reduce) {
    .cal-grid.is-anim { animation: none; }
    .cal-day-num { transition: none; }
    .cal-deco i { animation: none; }
  }

  /* 选中日任务列表：靠留白分段 */
  .cal-tasks { margin-top: 14px; padding: 0 4px 2px; }
  .cal-tasks[hidden] { display: none; }
  .cal-tasks-head { display: flex; align-items: center; gap: 8px; min-height: 24px; }
  .cal-tasks-title {
    flex: 1 1 auto;
    font-size: 13px;
    color: var(--cal-ink-2);
    font-variant-numeric: tabular-nums;
  }
  .cal-tasks-refresh {
    appearance: none;
    border: 0;
    background: transparent;
    color: var(--cal-accent);
    font: inherit;
    font-size: 12px;
    padding: 3px 8px;
    border-radius: 999px;
    cursor: pointer;
  }
  .cal-tasks-refresh:hover { background: var(--cal-hover); }
  .cal-tasks-refresh[hidden] { display: none; }
  .cal-task-list { list-style: none; margin: 6px 0 0; padding: 0; display: flex; flex-direction: column; }
  .cal-group-title {
    list-style: none;
    margin: 8px 4px 2px;
    font-size: 11px;
    color: var(--cal-ink-3);
  }
  .cal-task { display: flex; align-items: flex-start; gap: 8px; padding: 5px 4px; border-radius: 8px; }
  .cal-task:hover { background: var(--cal-hover); }
  .cal-task-state {
    flex: none;
    appearance: none;
    border: 0;
    background: transparent;
    padding: 0;
    width: 18px;
    text-align: center;
    font: inherit;
    font-size: 13px;
    line-height: 1.4;
    color: var(--cal-ink-3);
    cursor: pointer;
    border-radius: 50%;
  }
  .cal-task-state:disabled { cursor: default; }
  .cal-task-state:not(:disabled):hover { background: var(--cal-hover); color: var(--cal-ink); }
  .cal-task-state:focus-visible { outline: 2px solid var(--cal-accent); outline-offset: 1px; }
  .cal-task.is-done .cal-task-state,
  .cal-task.is-cancelled .cal-task-state { color: var(--cal-accent); }
  .cal-task-text { flex: 1 1 auto; min-width: 0; font-size: 14px; line-height: 1.4; overflow-wrap: anywhere; }
  .cal-task.is-done .cal-task-text { color: var(--cal-ink-3); text-decoration: line-through; }
  .cal-task.is-cancelled .cal-task-text { color: var(--cal-ink-3); text-decoration: line-through; opacity: 0.75; }
  .cal-task.is-overdue .cal-task-text { color: var(--cal-today); }
  .cal-task.is-overdue .cal-task-meta { color: var(--cal-today); }
  .cal-task-tag { color: var(--cal-accent); }
  .cal-task-meta {
    flex: none;
    font-size: 11px;
    line-height: 1.6;
    color: var(--cal-ink-3);
    white-space: nowrap;
  }
  .cal-tasks-note, .cal-tasks-empty, .cal-tasks-notice {
    margin: 8px 4px 0;
    font-size: 12px;
    line-height: 1.4;
    color: var(--cal-ink-3);
  }
  .cal-tasks-notice { color: var(--cal-warn); }
  .cal-tasks-note[hidden], .cal-tasks-empty[hidden], .cal-tasks-notice[hidden] { display: none; }

  /* 日记折叠块：正文 pre-wrap 保留换行 */
  .cal-note { margin: 12px 4px 0; }
  .cal-note[hidden] { display: none; }
  .cal-note-head {
    display: flex;
    align-items: baseline;
    gap: 6px;
    min-height: 22px;
    font-size: 12px;
    color: var(--cal-ink-2);
    cursor: pointer;
    list-style: none;
    border-radius: 6px;
    padding: 2px 2px;
  }
  .cal-note-head::-webkit-details-marker { display: none; }
  .cal-note-head:hover { color: var(--cal-ink); }
  .cal-note-glyph { flex: none; font-size: 11px; }
  .cal-note-title { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .cal-note-meta { flex: none; color: var(--cal-ink-3); font-variant-numeric: tabular-nums; }
  .cal-note-text {
    margin: 6px 0 0;
    padding: 0 2px;
    font-size: 13px;
    line-height: 1.5;
    color: var(--cal-ink-2);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    max-height: 320px;
    overflow-y: auto;
  }
  .cal-note-new {
    appearance: none;
    border: 0;
    background: transparent;
    color: var(--cal-accent);
    font: inherit;
    font-size: 13px;
    margin: 10px 4px 0;
    padding: 5px 10px;
    border-radius: 999px;
    cursor: pointer;
  }
  .cal-note-new:hover { background: var(--cal-hover); }
  .cal-note-new[hidden] { display: none; }

  /* 波纹：随指针扩散；可点元素加 .cal-rippleable */
  .cal-rippleable { position: relative; overflow: hidden; }
  .cal-ripple {
    position: absolute;
    left: 0;
    top: 0;
    width: 10px;
    height: 10px;
    margin: -5px 0 0 -5px;
    border-radius: 50%;
    pointer-events: none;
    background: radial-gradient(circle, var(--cal-ripple, rgba(0, 122, 255, 0.22)) 0%, transparent 70%);
    animation: cal-ripple-out 520ms cubic-bezier(0.22, 0.61, 0.36, 1) forwards;
  }
  @keyframes cal-ripple-out {
    0%   { transform: scale(0.2); opacity: 0.85; }
    100% { transform: scale(var(--cal-ripple-scale, 4)); opacity: 0; }
  }
  @media (prefers-reduced-motion: reduce) {
    .cal-ripple { display: none; }
  }

  /* 正文可编辑：悬停暗示，编辑换输入框 */
  .cal-task-text.is-editable { cursor: text; border-radius: 4px; }
  .cal-task-text.is-editable:hover { text-decoration: underline dotted var(--cal-ink-3); text-underline-offset: 3px; }
  .cal-task-input {
    flex: 1 1 auto;
    min-width: 0;
    margin: -2px 0;
    padding: 2px 6px;
    font: inherit;
    font-size: 14px;
    line-height: 1.4;
    color: var(--cal-ink);
    background: var(--cal-hover);
    border: 0;
    border-radius: 6px;
    outline: 2px solid var(--cal-accent);
    outline-offset: 1px;
  }

  /* Day Planner：进度条 + 时间轴 + 新建待办 */
  .cal-progress {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 8px 4px 0;
    font-size: 11px;
    color: var(--cal-ink-3);
    font-variant-numeric: tabular-nums;
  }
  .cal-progress[hidden] { display: none; }
  .cal-progress-bar {
    flex: 1 1 auto;
    height: 3px;
    border-radius: 999px;
    background: var(--cal-hover);
    overflow: hidden;
  }
  .cal-progress-bar > i {
    display: block;
    height: 100%;
    width: 0;
    border-radius: 999px;
    background: var(--cal-accent);
    transition: width 0.25s ease;
  }
  .cal-progress-text { flex: none; }

  .cal-timeline { margin: 10px 4px 0; }
  .cal-timeline[hidden] { display: none; }
  .cal-hour {
    position: relative;
    display: flex;
    gap: 8px;
    min-height: 26px;
    padding: 3px 0;
  }
  .cal-hour-label {
    flex: none;
    width: 40px;
    text-align: right;
    font-size: 11px;
    line-height: 1.5;
    color: var(--cal-ink-3);
    font-variant-numeric: tabular-nums;
  }
  .cal-hour-body {
    flex: 1 1 auto;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-left: 1px solid var(--cal-hover);   /* 时间轴主轨 */
    padding-left: 8px;
  }
  .cal-hour.is-empty .cal-hour-body { min-height: 16px; }
  .cal-gap {
    display: flex;
    gap: 8px;
    align-items: center;
    padding: 3px 0;
    font-size: 11px;
    color: var(--cal-ink-3);
  }
  .cal-gap-label { flex: none; width: 40px; text-align: right; font-variant-numeric: tabular-nums; }
  .cal-gap-text { flex: 1 1 auto; border-left: 1px solid var(--cal-hover); padding-left: 8px; }
  .cal-now {
    position: absolute;
    left: 40px;
    right: 0;
    height: 0;
    border-top: 1px solid var(--cal-today);
    pointer-events: none;
  }
  .cal-now::before {
    content: '';
    position: absolute;
    left: -3px;
    top: -3px;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--cal-today);
  }
  .cal-now-label {
    position: absolute;
    right: 0;
    top: -8px;
    font-size: 10px;
    line-height: 1;
    color: var(--cal-today);
    background: var(--cal-card-2, transparent);
    padding: 1px 3px;
    border-radius: 4px;
    font-variant-numeric: tabular-nums;
  }
  .cal-time-chip {
    flex: none;
    appearance: none;
    border: 0;
    background: transparent;
    color: var(--cal-accent);
    font: inherit;
    font-size: 11px;
    line-height: 1.6;
    padding: 0 4px;
    border-radius: 4px;
    cursor: pointer;
    font-variant-numeric: tabular-nums;
  }
  .cal-time-chip:hover { background: var(--cal-hover); }
  .cal-time-editor { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; }
  .cal-time-input {
    appearance: none;
    border: 0;
    border-radius: 6px;
    background: var(--cal-hover);
    color: var(--cal-ink);
    font: inherit;
    font-size: 12px;
    padding: 2px 4px;
    outline: 1px solid var(--cal-accent);
  }
  .cal-time-btn {
    appearance: none;
    border: 0;
    background: transparent;
    color: var(--cal-accent);
    font: inherit;
    font-size: 12px;
    padding: 2px 6px;
    border-radius: 6px;
    cursor: pointer;
  }
  .cal-time-btn:hover { background: var(--cal-hover); }
  .cal-time-btn.is-muted { color: var(--cal-ink-3); }

  .cal-add {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 12px 4px 0;
  }
  .cal-add[hidden] { display: none; }
  .cal-add-text {
    flex: 1 1 auto;
    min-width: 0;
    appearance: none;
    border: 0;
    border-radius: 8px;
    background: var(--cal-hover);
    color: var(--cal-ink);
    font: inherit;
    font-size: 13px;
    padding: 6px 8px;
  }
  .cal-add-text::placeholder { color: var(--cal-ink-3); }
  .cal-add-text:focus-visible, .cal-add-time:focus-visible { outline: 2px solid var(--cal-accent); outline-offset: 1px; }
  .cal-add-time {
    flex: none;
    width: 84px;
    appearance: none;
    border: 0;
    border-radius: 8px;
    background: var(--cal-hover);
    color: var(--cal-ink);
    font: inherit;
    font-size: 12px;
    padding: 5px 6px;
    font-variant-numeric: tabular-nums;
  }
  .cal-add-submit {
    flex: none;
    appearance: none;
    border: 0;
    border-radius: 999px;
    background: transparent;
    color: var(--cal-accent);
    font: inherit;
    font-size: 13px;
    padding: 5px 10px;
    cursor: pointer;
  }
  .cal-add-submit:hover { background: var(--cal-hover); }

  /* 内嵌：铺满宿主、卡片装饰收起 */
  /* normal 才让 iframe 透明、宿主底透出；dark 是不透明底 */
  html.cal-embed, html.cal-embed body { background: transparent; color-scheme: normal; }
  html.cal-embed body {
    display: block;
    padding: 0;
    min-height: 0;
  }
  html.cal-embed .cal {
    max-width: none;
    border: 0;
    border-radius: 0;
    /* 面板底来自宿主，只叠一层柔渐变 */
    background-image: linear-gradient(180deg, var(--cal-wash) 0%, transparent 260px);
    background-color: transparent;
    backdrop-filter: none;
    box-shadow: none;
    padding: 14px 12px 18px;
  }
  html.cal-embed .cal-deco { display: none; }
  html.cal-embed .cal-title { font-size: 26px; margin-top: 10px; }
  html.cal-embed .cal-day { height: 44px; }
  html.cal-embed .cal-day-num { width: 34px; height: 34px; font-size: 16px; }

  /* ═══ 皮肤 2：Windows 95 复古 ═══
     纯追加的覆盖层 —— 上面 Y2K 的规则一行未动，这里只做覆盖。
     本块必须在文件最后：与 html.cal-embed 同分 (0,2,1)，靠源码顺序决胜。 */
  html[data-cal-skin='win95'] {
    /* --cal-page-2/3 只喂 Y2K 的 body 渐变，本皮肤改用网纹覆盖，故不设 */
    --cal-page: #008080; /* 桌面青绿 */
    --cal-card: #c0c0c0; --cal-card-2: #c0c0c0; /* 面板灰 */
    --cal-ink: #000; --cal-ink-2: #404040; --cal-ink-3: #808080;
    --cal-hover: #d4d0c8;
    --cal-accent: #000080; --cal-accent-2: #1084d0; --cal-accent-ink: #fff; /* 海军蓝 */
    --cal-today: #800000; --cal-warn: #808000; /* 暗红 / 橄榄 */
    --cal-wash: #c0c0c0; --cal-ripple: rgba(0, 0, 128, 0.22);
    --cal-outside: 0.35; --cal-radius: 0;
    --cal-chrome: linear-gradient(90deg, #000080 0%, #1084d0 100%);
    --cal-gloss: #fff;
    --cal-face: #c0c0c0; --cal-raise: #fff; --cal-sink: #808080; --cal-field: #fff;
  }
  /* 夜间变体：仍是同一套复古语言，只是把面板压暗 */
  html[data-cal-skin='win95'][data-cal-theme='dark'] {
    --cal-page: #1a1a2e;
    --cal-card: #3a3a3a; --cal-card-2: #3a3a3a;
    --cal-ink: #e8e8e8; --cal-ink-2: #b0b0b0;
    --cal-hover: #4a4a4a;
    --cal-accent: #1084d0; --cal-accent-2: #3aa0e0; --cal-today: #ff8080;
    --cal-wash: #3a3a3a; --cal-ripple: rgba(16, 132, 208, 0.3);
    --cal-chrome: linear-gradient(90deg, #000040 0%, #0a5a9a 100%);
    --cal-face: #3a3a3a; --cal-raise: #5a5a5a; --cal-sink: #1a1a1a; --cal-field: #2a2a2a;
  }
  @media (prefers-color-scheme: dark) {
    html[data-cal-skin='win95'][data-cal-theme='auto'] {
      --cal-page: #1a1a2e;
      --cal-card: #3a3a3a; --cal-card-2: #3a3a3a;
      --cal-ink: #e8e8e8; --cal-ink-2: #b0b0b0;
      --cal-hover: #4a4a4a;
      --cal-accent: #1084d0; --cal-accent-2: #3aa0e0; --cal-today: #ff8080;
      --cal-wash: #3a3a3a; --cal-ripple: rgba(16, 132, 208, 0.3);
      --cal-chrome: linear-gradient(90deg, #000040 0%, #0a5a9a 100%);
      --cal-face: #3a3a3a; --cal-raise: #5a5a5a; --cal-sink: #1a1a1a; --cal-field: #2a2a2a;
    }
  }
  /* 桌面：平涂青绿 + 棋盘网纹（classic Mac 的 dither，纯 CSS 无图） */
  html[data-cal-skin='win95'] body {
    background-color: var(--cal-page);
    background-image: repeating-conic-gradient(rgba(0, 0, 0, 0.06) 0% 25%, transparent 0% 50%);
    background-size: 4px 4px;
  }
  html[data-cal-skin='win95'] .cal-deco { display: none; }
  /* 窗口外框：Win95 是凸起立体边，不是 Y2K 那种柔和投影 —— 必须显式清掉 */
  html[data-cal-skin='win95'] .cal {
    border: 2px solid;
    border-color: var(--cal-raise) var(--cal-sink) var(--cal-sink) var(--cal-raise);
    box-shadow: none; backdrop-filter: none;
  }
  /* 内嵌形态不画窗口框（侧栏要贴合宿主）*/
  html[data-cal-skin='win95'].cal-embed .cal { border: 0; box-shadow: none; }
  /* 窗口层序：真窗口的标题栏在最上，控件行降级为它下面的菜单/工具条。
     DOM 里 .cal-bar 排在 .cal-title 前面，这里用 flex order 翻转，不动 DOM、Y2K 零影响。
     注意 .cal-subtitle 也必须给 order，否则默认 0 会插到最前面。 */
  html[data-cal-skin='win95'] .cal-head { display: flex; flex-direction: column; }
  html[data-cal-skin='win95'] .cal-title { order: 1; }
  html[data-cal-skin='win95'] .cal-bar { order: 2; }
  html[data-cal-skin='win95'] .cal-subtitle { order: 3; }
  /* 窗口标题栏：h1 本身变成标题条；三个窗口键用伪元素 + box-shadow 画，不占 DOM */
  html[data-cal-skin='win95'] .cal-title {
    display: flex; align-items: center;
    margin: 0; padding: 3px 4px 3px 6px;
    font-family: 'VT323', 'Consolas', monospace;
    font-size: 19px; line-height: 1.25; letter-spacing: 0;
    background-image: var(--cal-chrome);
    -webkit-background-clip: border-box; background-clip: border-box;
    -webkit-text-fill-color: currentColor; color: var(--cal-accent-ink);
    filter: none; text-align: left;
  }
  html[data-cal-skin='win95'] .cal-title::after {
    /* margin-right 给 +16/+32 两个 box-shadow 预留位置，否则三键会长出标题栏右边缘 */
    content: ''; margin-left: auto; margin-right: 32px;
    width: 12px; height: 12px; flex: none;
    background: var(--cal-face); border: 1px solid var(--cal-raise);
    /* 前一个阴影盖在后一个上面：面色在前、亮边在后，凑出 1px 凸起 */
    box-shadow: 16px 0 0 0 var(--cal-face), 16px 0 0 1px var(--cal-raise),
                32px 0 0 0 var(--cal-face), 32px 0 0 1px var(--cal-raise);
  }
  /* MenuBar：控件行压成菜单条 */
  html[data-cal-skin='win95'] .cal-bar {
    background: var(--cal-face); border-bottom: 1px solid var(--cal-sink);
    padding: 1px 2px; min-height: 28px;
  }
  /* Button：凸起立体边（outset 自动从亮面色推暗面）*/
  html[data-cal-skin='win95'] .cal-btn,
  html[data-cal-skin='win95'] .cal-add-submit,
  html[data-cal-skin='win95'] .cal-tasks-refresh,
  html[data-cal-skin='win95'] .cal-time-btn {
    background: var(--cal-face); color: var(--cal-ink);
    border: 2px outset var(--cal-raise); border-radius: 0;
  }
  html[data-cal-skin='win95'] .cal-btn:active,
  html[data-cal-skin='win95'] .cal-add-submit:active,
  html[data-cal-skin='win95'] .cal-time-btn:active { border-style: inset; }
  /* 日期格：白底凹陷格，选中=海军蓝实心 */
  html[data-cal-skin='win95'] .cal-day {
    background: var(--cal-field); border: 1px solid var(--cal-sink); border-radius: 0;
  }
  html[data-cal-skin='win95'] .cal-day.is-selected .cal-day-num,
  html[data-cal-skin='win95'] .cal-day.is-selected:hover .cal-day-num {
    background-image: none; background-color: var(--cal-accent);
    color: var(--cal-accent-ink); border-radius: 0;
  }
  /* TextField：白底凹陷输入框 */
  html[data-cal-skin='win95'] .cal-add-text,
  html[data-cal-skin='win95'] .cal-add-time,
  html[data-cal-skin='win95'] .cal-time-input,
  html[data-cal-skin='win95'] .cal-task-input {
    background: var(--cal-field); color: var(--cal-ink);
    border: 2px inset var(--cal-sink); border-radius: 0;
  }
  /* ScrollBar：16px 粗滑块 + 网纹轨道（本页原本零滚动条样式）*/
  html[data-cal-skin='win95'] .cal-note-text::-webkit-scrollbar { width: 16px; height: 16px; }
  html[data-cal-skin='win95'] .cal-note-text::-webkit-scrollbar-thumb {
    background: var(--cal-face); border: 2px outset var(--cal-raise);
  }
  html[data-cal-skin='win95'] .cal-note-text::-webkit-scrollbar-track {
    background: repeating-conic-gradient(#fff 0% 25%, var(--cal-face) 0% 50%);
    background-size: 2px 2px;
  }
  /* 内嵌形态：标题条压矮，别把侧栏顶爆 */
  html[data-cal-skin='win95'].cal-embed .cal-title { font-size: 20px; margin-top: 0; }
  /* ═══ 皮肤 3：赛璐璐动画风 ═══
     粗黑描边 + 硬位移阴影 + 平面饱和色；本风格禁用渐变/模糊/圆角。
     同样只做覆盖，且与 cal-embed 同分 (0,2,1)，故必须留在文件最后。 */
  html[data-cal-skin='cel'] {
    --cal-page: #fafaf5; --cal-card: #ffffff; --cal-card-2: #ffffff;
    --cal-ink: #1a1a2e; --cal-ink-2: rgba(26, 26, 46, 0.62); --cal-ink-3: rgba(26, 26, 46, 0.40);
    --cal-hover: #fdf3cf; /* 平面淡黄，兼作悬停底与轨道线 */
    --cal-accent: #e63946; --cal-accent-2: #4ea8de; --cal-accent-ink: #fff;
    --cal-today: #e63946; --cal-warn: #f1c40f;
    --cal-wash: #fafaf5; --cal-ripple: rgba(26, 26, 46, 0.16);
    --cal-outside: 0.5; --cal-radius: 0;
    --cal-chrome: none; --cal-gloss: #1a1a2e; /* 本风格禁用渐变文字 */
  }
  /* 夜间：仍是同一套描边语言，只是把纸底换成墨底、描边转白 */
  html[data-cal-skin='cel'][data-cal-theme='dark'] {
    --cal-page: #141428; --cal-card: #1f1f38; --cal-card-2: #1f1f38;
    --cal-ink: #fafaf5; --cal-ink-2: rgba(250, 250, 245, 0.66); --cal-ink-3: rgba(250, 250, 245, 0.42);
    --cal-hover: #2b2b4a; --cal-gloss: #fafaf5;
  }
  @media (prefers-color-scheme: dark) {
    html[data-cal-skin='cel'][data-cal-theme='auto'] {
      --cal-page: #141428; --cal-card: #1f1f38; --cal-card-2: #1f1f38;
      --cal-ink: #fafaf5; --cal-ink-2: rgba(250, 250, 245, 0.66); --cal-ink-3: rgba(250, 250, 245, 0.42);
      --cal-hover: #2b2b4a; --cal-gloss: #fafaf5;
    }
  }
  html[data-cal-skin='cel'] body,
  html[data-cal-skin='cel'] .cal-title { font-family: 'Baloo 2', 'Nunito', system-ui, sans-serif; }
  /* 42 格数字留在系统栈：Baloo 2 没有表格数字，换过去圆圈会歪 */
  html[data-cal-skin='cel'] .cal-day-num { font-family: -apple-system, system-ui, sans-serif; }
  /* 表头星期不能用弱化墨色（=灰，本风格禁止低饱和）：改用实心墨 + 黑体。
     没上强调色是算过对比度的——12px 正文要 4.5:1，而 #4ea8de 在米白底上只有 2.6:1、
     #e63946 也只有 4.1:1，都不够；墨色在浅深两个主题下都远超。 */
  html[data-cal-skin='cel'] .cal-weekday {
    color: var(--cal-gloss); font-weight: 900; text-transform: uppercase; letter-spacing: 0.06em;
  }
  html[data-cal-skin='cel'] body { background-image: none; background-color: var(--cal-page); }
  html[data-cal-skin='cel'] .cal-deco { display: none; }
  /* 卡片：3px 粗黑描边 + 4px 硬阴影，无渐变无模糊 */
  html[data-cal-skin='cel'] .cal {
    background-image: none; background-color: var(--cal-card);
    border: 3px solid var(--cal-gloss); border-radius: 0;
    box-shadow: 4px 4px 0 var(--cal-gloss); backdrop-filter: none;
  }
  html[data-cal-skin='cel'].cal-embed .cal { border: 0; box-shadow: none; }
  /* 标题：粗黑实心字；解掉 Y2K 的渐变裁切 */
  html[data-cal-skin='cel'] .cal-title {
    background-image: none;
    -webkit-background-clip: border-box; background-clip: border-box;
    -webkit-text-fill-color: currentColor; color: var(--cal-ink);
    filter: none; font-weight: 900; text-transform: uppercase; letter-spacing: -0.01em;
  }
  /* 按钮：硬阴影随按下位移收缩，75ms 线性（卡通抽帧感，禁 ease-in-out） */
  html[data-cal-skin='cel'] .cal-btn,
  html[data-cal-skin='cel'] .cal-add-submit,
  html[data-cal-skin='cel'] .cal-tasks-refresh,
  html[data-cal-skin='cel'] .cal-time-btn,
  html[data-cal-skin='cel'] .cal-task-state {
    background: var(--cal-accent); color: #fff; font-weight: 900; text-transform: uppercase;
    border: 3px solid var(--cal-gloss); border-radius: 0;
    box-shadow: 3px 3px 0 var(--cal-gloss);
    transition: transform 75ms linear, box-shadow 75ms linear, background-color 75ms linear;
  }
  html[data-cal-skin='cel'] .cal-btn:hover,
  html[data-cal-skin='cel'] .cal-add-submit:hover { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--cal-gloss); }
  /* 挤压拉伸：横向撑开、纵向压扁，阴影瞬间归零（硬碰撞感） */
  html[data-cal-skin='cel'] .cal-btn:active,
  html[data-cal-skin='cel'] .cal-add-submit:active,
  html[data-cal-skin='cel'] .cal-time-btn:active {
    transform: translate(3px, 3px) scale(1.1, 0.9); box-shadow: none;
  }
  /* 高光扫过：白色斜条纹 hover 时掠过按钮 */
  html[data-cal-skin='cel'] .cal-btn::after {
    content: ''; position: absolute; top: 0; bottom: 0; left: 0; width: 40%;
    background: rgba(255, 255, 255, 0.3); transform: translateX(-200%) skewX(-12deg);
    transition: transform 75ms linear; pointer-events: none;
  }
  html[data-cal-skin='cel'] .cal-btn:hover::after { transform: translateX(260%) skewX(-12deg); }
  /* 焦点环：按钮底色本身就是强调红，沿用默认的 --cal-accent 环会完全看不见。
     改用墨色描边 + 外扩留缝（环落在白卡上，对比度足够，且与按钮自己的黑边分得开）。 */
  html[data-cal-skin='cel'] .cal-btn:focus-visible,
  html[data-cal-skin='cel'] .cal-add-submit:focus-visible,
  html[data-cal-skin='cel'] .cal-tasks-refresh:focus-visible,
  html[data-cal-skin='cel'] .cal-time-btn:focus-visible,
  html[data-cal-skin='cel'] .cal-task-state:focus-visible {
    outline: 3px solid var(--cal-gloss); outline-offset: 2px;
  }
  @media (prefers-reduced-motion: reduce) {
    /* 本风格的位移 / 挤压 / 斜条纹扫过都是装饰性运动，减少动态效果时一律取消。
       保留硬阴影的收缩：那是静态视觉反馈，不是运动。 */
    html[data-cal-skin='cel'] .cal-btn,
    html[data-cal-skin='cel'] .cal-add-submit,
    html[data-cal-skin='cel'] .cal-tasks-refresh,
    html[data-cal-skin='cel'] .cal-time-btn,
    html[data-cal-skin='cel'] .cal-task-state { transition: none; }
    html[data-cal-skin='cel'] .cal-btn:hover,
    html[data-cal-skin='cel'] .cal-add-submit:hover,
    html[data-cal-skin='cel'] .cal-tasks-refresh:hover,
    html[data-cal-skin='cel'] .cal-time-btn:hover,
    html[data-cal-skin='cel'] .cal-task-state:hover,
    html[data-cal-skin='cel'] .cal-btn:active,
    html[data-cal-skin='cel'] .cal-add-submit:active,
    html[data-cal-skin='cel'] .cal-tasks-refresh:active,
    html[data-cal-skin='cel'] .cal-time-btn:active,
    html[data-cal-skin='cel'] .cal-task-state:active { transform: none; }
    html[data-cal-skin='cel'] .cal-btn::after { display: none; }
  }
  /* 日期格：粗描边直角块（网格太密，不叠位移阴影，否则会压到邻格） */
  html[data-cal-skin='cel'] .cal-day {
    background: var(--cal-card); border: 3px solid var(--cal-gloss); border-radius: 0;
  }
  html[data-cal-skin='cel'] .cal-day.is-selected .cal-day-num,
  html[data-cal-skin='cel'] .cal-day.is-selected:hover .cal-day-num {
    background-image: none; background-color: var(--cal-accent); color: #fff; border-radius: 0;
  }
  /* 输入框：3px 描边，聚焦环用强调红——与自身的黑描边分得开，且在米白底上有 4.1:1 */
  html[data-cal-skin='cel'] .cal-add-text,
  html[data-cal-skin='cel'] .cal-add-time,
  html[data-cal-skin='cel'] .cal-time-input,
  html[data-cal-skin='cel'] .cal-task-input {
    background: var(--cal-card); color: var(--cal-ink);
    border: 3px solid var(--cal-gloss); border-radius: 0;
  }
  html[data-cal-skin='cel'] .cal-add-text:focus-visible,
  html[data-cal-skin='cel'] .cal-add-time:focus-visible,
  html[data-cal-skin='cel'] .cal-time-input:focus-visible,
  html[data-cal-skin='cel'] .cal-task-input:focus-visible {
    outline: 3px solid var(--cal-accent); outline-offset: 0;
  }
  html[data-cal-skin='cel'] .cal-timeline, html[data-cal-skin='cel'] .cal-progress-bar { border-radius: 0; }
  html[data-cal-skin='cel'] .cal-progress-bar { border: 2px solid var(--cal-gloss); background: var(--cal-card); }
  html[data-cal-skin='cel'] .cal-progress-bar i { background: var(--cal-accent-2); }
  /* 切换按钮（两套皮肤共用基础样式，立体边由上面的 .cal-btn 规则补） */
  .cal-skin { font-size: 13px; font-weight: 700; padding: 5px 9px; margin-left: 2px; }
</style>
</head>
<body>
  <main class="cal" id="cal" aria-label="月历">
    <header class="cal-head">
      <div class="cal-deco" aria-hidden="true"><i></i><i></i><svg class="cal-fly" viewBox="0 0 24 24"><path d="M11 12C8 6 2 3 1 7C0 10 6 12 11 12ZM11 12C8 18 2 21 1 17C0 14 6 12 11 12ZM13 12C16 6 22 3 23 7C24 10 18 12 13 12ZM13 12C16 18 22 21 23 17C24 14 18 12 13 12Z"/><ellipse cx="12" cy="12" rx="1" ry="5"/></svg></div>
      <div class="cal-bar">
        <button class="cal-btn cal-rippleable" id="calTodayBtn" type="button" hidden>今天</button>
        <span class="cal-bar-spacer"></span>
        <button class="cal-btn cal-arrow cal-rippleable" id="calPrev" type="button" aria-label="上一月">
          <svg viewBox="0 0 16 16" fill="none" aria-hidden="true">
            <path d="M10 2.5 4.5 8l5.5 5.5" stroke="currentColor" stroke-width="1.8"
              stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </button>
        <button class="cal-btn cal-arrow cal-rippleable" id="calNext" type="button" aria-label="下一月">
          <svg viewBox="0 0 16 16" fill="none" aria-hidden="true">
            <path d="M6 2.5 11.5 8 6 13.5" stroke="currentColor" stroke-width="1.8"
              stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </button>
        <button class="cal-btn cal-skin cal-rippleable" id="calSkinBtn" type="button"></button>
      </div>
      <h1 class="cal-title" id="calTitle">—</h1>
      <p class="cal-subtitle" id="calSubtitle">—</p>
    </header>
    <div class="cal-weekdays" id="calWeekdays" aria-hidden="true"></div>
    <div class="cal-grid" id="calGrid" tabindex="0" role="group" aria-label="日期"></div>
    <section class="cal-tasks" id="calTasks" aria-label="选中日期的任务" hidden>
      <div class="cal-tasks-head">
        <span class="cal-tasks-title" id="calTasksTitle"></span>
        <button class="cal-tasks-refresh cal-rippleable" id="calTasksRefresh" type="button">刷新</button>
      </div>
      <div class="cal-progress" id="calProgress" hidden>
        <span class="cal-progress-bar"><i id="calProgressFill"></i></span>
        <span class="cal-progress-text" id="calProgressText"></span>
      </div>
      <div class="cal-timeline" id="calTimeline" hidden aria-label="当天时间轴"></div>
      <ul class="cal-task-list" id="calTaskList"></ul>
      <p class="cal-tasks-empty" id="calTasksEmpty" hidden></p>
      <form class="cal-add" id="calAdd" hidden>
        <input class="cal-add-text" id="calAddText" type="text" maxlength="200" placeholder="新建待办…" aria-label="新建待办">
        <input class="cal-add-time" id="calAddTime" type="time" step="600" aria-label="开始时间（可留空）">
        <button class="cal-add-submit cal-rippleable" id="calAddSubmit" type="submit">添加</button>
      </form>
      <p class="cal-tasks-notice" id="calTasksNotice" hidden></p>
      <details class="cal-note" id="calNote" hidden>
        <summary class="cal-note-head cal-rippleable">
          <span class="cal-note-glyph" aria-hidden="true">📓</span>
          <span class="cal-note-title" id="calNoteTitle"></span>
          <span class="cal-note-meta" id="calNoteMeta"></span>
        </summary>
        <div class="cal-note-text" id="calNoteText"></div>
      </details>
      <button class="cal-note-new cal-rippleable" id="calNoteNew" type="button" hidden>新建这一天的日记</button>
      <p class="cal-tasks-note" id="calTasksNote" hidden></p>
    </section>
  </main>

<script>
  // 文件说明：单文件零依赖月历 + Obsidian 任务/日记同步面板。
  // 完整设计说明、语法表、写回护栏与验收记录见仓库里的两个 README（此处不再重复注释）。

(function () {
  'use strict'

  var WEEKDAY_SHORT = ['一', '二', '三', '四', '五', '六', '日']
  var WEEKDAY_FULL = ['星期一', '星期二', '星期三', '星期四', '星期五', '星期六', '星期日']
  var CELLS = 42
  var SWIPE_MIN = 48
  var SWIPE_SLOP = 6

  var query = new URLSearchParams(location.search)
  var themeParam = (query.get('theme') || '').toLowerCase()
  var embed = query.get('embed') === '1'
  document.documentElement.dataset.calTheme =
    (themeParam === 'light' || themeParam === 'dark') ? themeParam : 'auto'
  if (embed) document.documentElement.classList.add('cal-embed')

  var els = {
    title: document.getElementById('calTitle'),
    subtitle: document.getElementById('calSubtitle'),
    weekdays: document.getElementById('calWeekdays'),
    grid: document.getElementById('calGrid'),
    prev: document.getElementById('calPrev'),
    next: document.getElementById('calNext'),
    todayBtn: document.getElementById('calTodayBtn'),
    skinBtn: document.getElementById('calSkinBtn'),
    tasks: document.getElementById('calTasks'),
    tasksTitle: document.getElementById('calTasksTitle'),
    tasksRefresh: document.getElementById('calTasksRefresh'),
    taskList: document.getElementById('calTaskList'),
    tasksEmpty: document.getElementById('calTasksEmpty'),
    tasksNotice: document.getElementById('calTasksNotice'),
    tasksNote: document.getElementById('calTasksNote'),
    progress: document.getElementById('calProgress'),
    progressFill: document.getElementById('calProgressFill'),
    progressText: document.getElementById('calProgressText'),
    timeline: document.getElementById('calTimeline'),
    add: document.getElementById('calAdd'),
    addText: document.getElementById('calAddText'),
    addTime: document.getElementById('calAddTime'),
    note: document.getElementById('calNote'),
    noteTitle: document.getElementById('calNoteTitle'),
    noteMeta: document.getElementById('calNoteMeta'),
    noteText: document.getElementById('calNoteText'),
    noteNew: document.getElementById('calNoteNew')
  }

  function pad2(n) { return n < 10 ? '0' + n : String(n) }
  function startOfDay(d) { return new Date(d.getFullYear(), d.getMonth(), d.getDate()) }
  function keyOf(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) }
  function mondayIndex(d) { return (d.getDay() + 6) % 7 }

  var today = startOfDay(new Date())
  var state = {
    year: today.getFullYear(),
    month: today.getMonth(),
    selected: keyOf(today)
  }

  // #region 任务展示
  var MAX_DOTS = 3
  var PRIORITY_RANK = { highest: 0, high: 1, medium: 2, low: 3, lowest: 4 }
  var PRIORITY_GLYPH = { highest: '🔺', high: '⏫', medium: '🔼', low: '🔽', lowest: '⏬' }
  var STATE_GLYPH = { todo: '○', done: '✓', cancelled: '✕' }

  function taskRank(task) {
    if (task.state === 'todo') return 0
    if (task.state === 'done') return 1
    return 2
  }

  function taskKind(task, todayKey) {
    if (task.state !== 'todo') return 'done'
    if (task.date && task.date < todayKey) return 'overdue'
    if (task.priority === 'highest' || task.priority === 'high') return 'priority'
    return 'open'
  }

  function urgencyOf(task, todayKey) {
    if (task.date && todayKey && task.date < todayKey) return 0
    if (task.priority === 'highest' || task.priority === 'high') return 1
    if (task.date) return 2
    return 3
  }

  function sortDayTasks(tasks, todayKey) {
    return tasks.slice().sort(function (a, b) {
      var rank = taskRank(a) - taskRank(b)
      if (rank !== 0) return rank
      var urgency = urgencyOf(a, todayKey) - urgencyOf(b, todayKey)
      if (urgency !== 0) return urgency
      var pa = PRIORITY_RANK[a.priority] === undefined ? 9 : PRIORITY_RANK[a.priority]
      var pb = PRIORITY_RANK[b.priority] === undefined ? 9 : PRIORITY_RANK[b.priority]
      if (pa !== pb) return pa - pb
      var da = a.date || '9999-12-31'
      var db = b.date || '9999-12-31'
      if (da !== db) return da < db ? -1 : 1
      return String(a.text || '').localeCompare(String(b.text || ''), 'zh-Hans-CN')
    })
  }

  function classifyDay(tasks, todayKey) {
    var sorted = sortDayTasks(tasks || [], todayKey)
    var open = 0
    for (var i = 0; i < sorted.length; i++) if (sorted[i].state === 'todo') open += 1
    return {
      total: sorted.length,
      open: open,
      dots: sorted.slice(0, MAX_DOTS).map(function (task) { return taskKind(task, todayKey) })
    }
  }

  function formatDayTitle(dateKey, count, todayKey) {
    var parts = dateKey.split('-')
    var d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]))
    var head = (dateKey === todayKey ? '今天 · ' : '') +
      (d.getMonth() + 1) + '月' + d.getDate() + '日 ' + WEEKDAY_FULL[mondayIndex(d)]
    return count > 0 ? head + ' · ' + count + ' 个任务' : head
  }

  function taskMetaOf(task, todayKey) {
    var meta = []
    if (task.priority && PRIORITY_GLYPH[task.priority]) meta.push(PRIORITY_GLYPH[task.priority])
    if (task.recurrence) meta.push('🔁')
    if (task.dateSource === 'scheduled') meta.push('⏳')
    else if (task.dateSource === 'start') meta.push('🛫')
    else if (task.dateSource === 'note') meta.push('📓')
    if (task.state === 'todo' && task.date && task.date < todayKey) meta.push('逾期')
    return meta
  }

  function tasksUrl(refresh) {
    if (query.get('tasks') === '0' || query.get('tasks') === 'off') return null
    var parts = []
    var session = query.get('session')
    if (session) parts.push('session=' + encodeURIComponent(session))
    var root = query.get('root')
    if (root) parts.push('root=' + encodeURIComponent(root))
    if (refresh) parts.push('refresh=1')
    return '/dsh-calendar/tasks' + (parts.length ? '?' + parts.join('&') : '')
  }

  function rootQuery() {
    var parts = []
    var session = query.get('session')
    if (session) parts.push('session=' + encodeURIComponent(session))
    var root = query.get('root')
    if (root) parts.push('root=' + encodeURIComponent(root))
    return parts.length ? '?' + parts.join('&') : ''
  }

  function nextState(task) {
    return task && task.state === 'done' ? 'todo' : 'done'
  }

  function formatBytes(bytes) {
    var n = Number(bytes) || 0
    if (n < 1024) return n + ' B'
    if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB'
    return (n / 1024 / 1024).toFixed(1) + ' MB'
  }

  function noteSummary(note) {
    if (!note) return null
    var meta = []
    if (note.words) meta.push(formatWords(note.words))
    else if (note.bytes) meta.push(formatBytes(note.bytes))
    if (note.taskCount) meta.push(note.taskCount + ' 个任务')
    return { title: '日记', meta: meta.join(' · ') }
  }

  function formatWords(count) {
    var n = Math.max(0, Math.round(Number(count) || 0))
    if (n < 1000) return n + ' 词'
    return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'k 词'
  }

  function noteDotCount(note, wordsPerDot, maxNoteDots) {
    if (!note) return 0
    var words = Number(note.words) || 0
    var step = Number(wordsPerDot) || 250
    var cap = Math.max(1, Number(maxNoteDots) || 2)
    if (words <= 0) return 0
    return Math.min(cap, Math.max(1, Math.floor(words / step)))
  }

  function hasTime(task) {
    return Boolean(task) && task.startMinutes !== null && task.startMinutes !== undefined
  }

  function effectiveEnd(task, defaultDuration) {
    if (!hasTime(task)) return null
    if (task.endMinutes !== null && task.endMinutes !== undefined) return task.endMinutes
    return task.startMinutes + (Number(defaultDuration) || 30)
  }

  function formatDuration(minutes) {
    var n = Math.max(0, Math.round(Number(minutes) || 0))
    if (n < 60) return n + 'm'
    var h = Math.floor(n / 60)
    var m = n % 60
    return m === 0 ? h + 'h' : h + 'h' + m + 'm'
  }

  function timeChipLabel(task) {
    if (!hasTime(task) || !task.startTime) return ''
    return task.endTime ? task.startTime + ' - ' + task.endTime : task.startTime
  }

  function clockMinutes(value) {
    var m = /^(\d{1,2}):(\d{2})$/.exec(String(value || '').trim())
    return m ? Number(m[1]) * 60 + Number(m[2]) : null
  }

  function dayProgress(tasks) {
    var total = tasks.length
    var done = 0
    var scheduled = 0
    for (var i = 0; i < total; i++) {
      if (tasks[i].state === 'done') done += 1
      if (hasTime(tasks[i])) scheduled += 1
    }
    return {
      total: total,
      done: done,
      open: total - done,
      scheduled: scheduled,
      pct: total === 0 ? 0 : Math.round((done / total) * 100)
    }
  }

  function buildTimeline(scheduled, options) {
    var opts = options || {}
    var defaultDuration = Number(opts.defaultDurationMinutes) || 30
    var nowMinutes = opts.nowMinutes === null || opts.nowMinutes === undefined ? null : Number(opts.nowMinutes)
    var hours = Object.create(null)
    for (var i = 0; i < scheduled.length; i++) {
      var task = scheduled[i]
      var from = Math.floor(task.startMinutes / 60) - 1
      var to = Math.ceil(effectiveEnd(task, defaultDuration) / 60) + 1
      for (var h = from; h <= to; h++) if (h >= 0 && h <= 23) hours[h] = true
    }
    if (nowMinutes !== null) {
      var centre = Math.floor(nowMinutes / 60)
      for (var k = centre - 1; k <= centre + 1; k++) if (k >= 0 && k <= 23) hours[k] = true
    }
    var list = Object.keys(hours).map(Number).sort(function (a, b) { return a - b })
    if (list.length === 0) return { rows: [], now: null }

    var byHour = Object.create(null)
    for (var j = 0; j < scheduled.length; j++) {
      var item = scheduled[j]
      var hour = Math.floor(item.startMinutes / 60)
      ;(byHour[hour] = byHour[hour] || []).push(item)
    }

    var rows = []
    for (var idx = 0; idx < list.length; idx++) {
      var current = list[idx]
      if (idx > 0 && current - list[idx - 1] > 1) {
        rows.push({ type: 'gap', from: list[idx - 1], to: current, label: list[idx - 1] + ':00' })
      }
      var row = { type: 'hour', hour: current, label: current + ':00', tasks: byHour[current] || [] }
      if (nowMinutes !== null && Math.floor(nowMinutes / 60) === current) {
        row.nowOffsetPct = ((nowMinutes % 60) / 60) * 100
      }
      rows.push(row)
    }
    var nowHour = nowMinutes === null ? null : Math.floor(nowMinutes / 60)
    var now = nowHour !== null && hours[nowHour]
      ? { hour: nowHour, offsetPct: ((nowMinutes % 60) / 60) * 100 }
      : null
    return { rows: rows, now: now }
  }

  function sortScheduled(tasks) {
    return tasks.slice().sort(function (a, b) {
      if (a.startMinutes !== b.startMinutes) return a.startMinutes - b.startMinutes
      return String(a.text || '').localeCompare(String(b.text || ''), 'zh-Hans-CN')
    })
  }

  function dayTooltip(dateKey, tasks, todayKey, note) {
    var parts = dateKey.split('-')
    var d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]))
    var head = (dateKey === todayKey ? '今天 · ' : '') + (d.getMonth() + 1) + '月' + d.getDate() + '日 ' + WEEKDAY_FULL[mondayIndex(d)]
    var bits = [head]
    if (note) bits.push('已写 ' + formatWords(note.words))
    else bits.push('还没写日记')
    if (tasks.length > 0) {
      var progress = dayProgress(tasks)
      bits.push(progress.done + '/' + progress.total + ' 个任务完成' + (progress.scheduled > 0 ? '，' + progress.scheduled + ' 个已排时间' : ''))
    }
    return bits.join(' · ')
  }

  function writeErrorText(result) {
    if (!result) return '写回失败'
    if (result.error === 'stale') return '文件已被外部修改，已重新读取；请重试'
    if (result.error === 'root-not-allowed') return '该文件不在允许的笔记库内，已拒绝写回'
    if (result.error === 'outside-root') return '路径越界，已拒绝写回'
    if (result.error === 'write-disabled') return '写回已在插件配置里关闭'
    if (result.error === 'write-failed') return '写入失败（文件可能被 Obsidian 占用）'
    if (result.error === 'verify-failed') return '写入校验未通过，文件可能未改动'
    if (result.error === 'not-a-task') return '该行已经不是任务了，已重新读取'
    if (result.error === 'bad-time') return '时间不合法（结束时间要晚于开始时间，格式 HH:mm）'
    if (result.error === 'bad-date') return '日期不合法'
    if (result.error === 'bad-text') return '内容不能为空，也不能带换行'
    if (result.error === 'text-too-long') return '内容太长（上限 200 字）'
    if (result.error === 'create-disabled') return '新建已在插件配置里关闭'
    if (result.error === 'exists') return '已经存在了'
    return '写回失败：' + String(result.error || 'unknown')
  }
  // #endregion

  var TASKS = {
    enabled: true,
    byDate: {},
    notes: {},
    undated: 0,
    scanned: null,
    loaded: false,
    note: '',
    error: null,
    root: null,
    caps: { write: false, create: false, appendDoneDate: true, schedule: false, add: false },
    planner: { defaultDurationMinutes: 30, showNow: true, startHour: 6 },
    calendar: { wordsPerDot: 250, maxNoteDots: 2 },
    busy: false,
    notice: ''
  }

  function loadTasks(refresh) {
    var url = tasksUrl(refresh)
    if (!url) { TASKS.enabled = false; TASKS.byDate = {}; renderTasks(); render(state.offset || 0); return }
    var request
    try {
      request = fetch(url, { headers: { accept: 'application/json' } })
    } catch (error) {
      finishTasks(null, error)
      return
    }
    request.then(function (response) {
      return response.ok ? response.json() : null
    }).then(function (data) {
      finishTasks(data, null)
    }).catch(function (error) {
      finishTasks(null, error)
    })
  }

  function finishTasks(data, error) {
    if (!data || data.ok === false) {
      TASKS.byDate = {}
      TASKS.notes = {}
      TASKS.undated = 0
      TASKS.scanned = null
      TASKS.note = ''
      TASKS.root = null
      TASKS.caps = { write: false, create: false, appendDoneDate: true, schedule: false, add: false }
      TASKS.error = error ? 'unreachable' : ((data && data.error) || 'unavailable')
    } else {
      TASKS.byDate = data.buckets || {}
      TASKS.notes = data.notes || {}
      TASKS.undated = (data.counts && data.counts.undated) || 0
      TASKS.scanned = data.scanned || null
      TASKS.root = data.root || null
      TASKS.caps = data.capabilities || { write: false, create: false, appendDoneDate: true, schedule: false, add: false }
      if (data.dayPlanner) TASKS.planner = data.dayPlanner
      if (data.calendar) TASKS.calendar = data.calendar
      TASKS.error = null
      var notes = []
      if (TASKS.undated > 0) notes.push('另有 ' + TASKS.undated + ' 个未排期任务（没有 📅/⏳/🛫 日期）')
      if (TASKS.scanned && TASKS.scanned.truncated) notes.push('文件较多，仅扫描了前 ' + TASKS.scanned.files + ' 个 Markdown')
      TASKS.note = notes.join(' · ')
    }
    TASKS.loaded = true
    renderTasks()
    render(0)
  }

  function postWrite(path, payload) {
    return fetch(path + rootQuery(), {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-dsh-calendar': 'write' },
      body: JSON.stringify(payload)
    }).then(function (response) {
      return response.json().catch(function () { return null })
    })
  }

  function toggleTask(task) {
    if (!TASKS.caps.write || TASKS.busy) return
    var previous = { state: task.state, done: task.done }
    var target = nextState(task)
    task.state = target
    if (target === 'done' && TASKS.caps.appendDoneDate) task.done = keyOf(today)
    if (target !== 'done') task.done = null
    TASKS.busy = true
    TASKS.notice = ''
    render(0)

    var url = '/dsh-calendar/tasks/toggle'
    var payload = { file: task.file, line: task.line, done: target === 'done', expect: task.raw, date: keyOf(today) }
    var request
    try {
      request = fetch(url + rootQuery(), {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-dsh-calendar': 'write' },
        body: JSON.stringify(payload)
      })
    } catch (error) {
      finishToggle(task, previous, null, error)
      return
    }
    request.then(function (response) {
      return response.json().catch(function () { return null })
    }).then(function (result) {
      finishToggle(task, previous, result, null)
    }).catch(function (error) {
      finishToggle(task, previous, null, error)
    })
  }

  function finishToggle(task, previous, result, error) {
    TASKS.busy = false
    if (!result || result.ok !== true) {
      task.state = previous.state
      task.done = previous.done
      TASKS.notice = error ? '写回失败：连不上 host' : writeErrorText(result)
    } else {
      if (typeof result.after === 'string') task.raw = result.after
      TASKS.notice = ''
    }
    loadTasks(true)
  }

  function beginEdit(task, textEl, row) {
    if (!TASKS.caps.write || TASKS.busy) return
    if (row.querySelector('.cal-task-input')) return

    var input = document.createElement('input')
    input.type = 'text'
    input.className = 'cal-task-input'
    input.value = task.text || ''
    input.maxLength = 500
    input.setAttribute('aria-label', '编辑任务内容')
    textEl.hidden = true
    row.insertBefore(input, textEl.nextSibling)
    input.focus()
    input.select()

    var settled = false
    function cancel() {
      settled = true
      if (input.parentNode) input.parentNode.removeChild(input)
      textEl.hidden = false
    }
    function commit() {
      if (settled) return
      settled = true
      var next = input.value.replace(/\s+/g, ' ').trim()
      if (input.parentNode) input.parentNode.removeChild(input)
      textEl.hidden = false
      if (next === '' || next === (task.text || '')) return
      var previous = task.text
      task.text = next
      TASKS.busy = true
      TASKS.notice = ''
      render(0)
      var payload = { file: task.file, line: task.line, expect: task.raw, text: next }
      postWrite('/dsh-calendar/tasks/update', payload).then(function (result) {
        TASKS.busy = false
        if (!result || result.ok !== true) {
          task.text = previous
          TASKS.notice = writeErrorText(result)
        } else if (typeof result.after === 'string') {
          task.raw = result.after
          TASKS.notice = ''
        }
        loadTasks(true)
      }).catch(function () {
        TASKS.busy = false
        task.text = previous
        TASKS.notice = '写回失败：连不上 host'
        render(0)
      })
    }

    input.addEventListener('keydown', function (event) {
      event.stopPropagation()
      if (event.key === 'Enter') { event.preventDefault(); commit() }
      else if (event.key === 'Escape') { event.preventDefault(); cancel() }
    })
    input.addEventListener('blur', commit)
  }

  function spawnRipple(host, clientX, clientY) {
    var rect = host.getBoundingClientRect()
    if (!rect.width || !rect.height) return
    var ripple = document.createElement('span')
    ripple.className = 'cal-ripple'
    ripple.style.left = (clientX - rect.left) + 'px'
    ripple.style.top = (clientY - rect.top) + 'px'
    ripple.style.setProperty('--cal-ripple-scale', String(Math.max(rect.width, rect.height) / 8))
    host.appendChild(ripple)
    var remove = function () { if (ripple.parentNode) ripple.parentNode.removeChild(ripple) }
    ripple.addEventListener('animationend', remove)
    setTimeout(remove, 900)
  }

  function beginTimeEdit(task, chip, row) {
    if (!TASKS.caps.schedule || TASKS.busy) return
    if (row.querySelector('.cal-time-editor')) return

    var editor = document.createElement('span')
    editor.className = 'cal-time-editor'
    var start = document.createElement('input')
    start.type = 'time'
    start.step = '600'
    start.className = 'cal-time-input'
    start.value = task.startTime || ''
    start.setAttribute('aria-label', '开始时间')
    var dash = document.createElement('span')
    dash.className = 'cal-time-btn is-muted'
    dash.textContent = '–'
    var end = document.createElement('input')
    end.type = 'time'
    end.step = '600'
    end.className = 'cal-time-input'
    end.value = task.endTime || ''
    end.setAttribute('aria-label', '结束时间（可留空）')
    var save = document.createElement('button')
    save.type = 'button'
    save.className = 'cal-time-btn cal-rippleable'
    save.textContent = '✓'
    save.title = '保存时间'
    var clear = document.createElement('button')
    clear.type = 'button'
    clear.className = 'cal-time-btn is-muted cal-rippleable'
    clear.textContent = '清除'
    clear.title = '移除时间（这条回到"未安排"）'
    var cancel = document.createElement('button')
    cancel.type = 'button'
    cancel.className = 'cal-time-btn is-muted cal-rippleable'
    cancel.textContent = '✕'
    cancel.title = '取消'

    editor.appendChild(start)
    editor.appendChild(dash)
    editor.appendChild(end)
    editor.appendChild(save)
    editor.appendChild(clear)
    editor.appendChild(cancel)
    chip.hidden = true
    row.insertBefore(editor, chip)

    var settled = false
    function close() {
      settled = true
      if (editor.parentNode) editor.parentNode.removeChild(editor)
      chip.hidden = false
    }
    function commit(clearIt) {
      if (settled) return
      var from = start.value || ''
      var to = end.value || ''
      if (!clearIt) {
        if (from === '' && to !== '') { from = to; to = '' }
        if (from === '') {
          TASKS.notice = '请先选开始时间，或用「清除」把这条变回未安排'
          close()
          renderTasks()
          return
        }
      }
      close()
      saveTaskTime(task, clearIt ? null : from, clearIt ? null : (to === '' ? null : to))
    }

    save.addEventListener('click', function () { commit(false) })
    clear.addEventListener('click', function () { commit(true) })
    cancel.addEventListener('click', function () { close() })
    editor.addEventListener('keydown', function (event) {
      event.stopPropagation()
      if (event.key === 'Enter') { event.preventDefault(); commit(false) }
      else if (event.key === 'Escape') { event.preventDefault(); close() }
    })
    start.focus()
  }

  function saveTaskTime(task, start, end) {
    var previous = {
      startTime: task.startTime,
      endTime: task.endTime,
      startMinutes: task.startMinutes,
      endMinutes: task.endMinutes
    }
    task.startTime = start
    task.endTime = end
    task.startMinutes = start === null ? null : clockMinutes(start)
    task.endMinutes = end === null ? null : clockMinutes(end)
    TASKS.busy = true
    TASKS.notice = ''
    render(0)
    postWrite('/dsh-calendar/tasks/schedule', {
      file: task.file,
      line: task.line,
      expect: task.raw,
      start: start,
      end: end
    }).then(function (result) {
      TASKS.busy = false
      if (!result || result.ok !== true) {
        task.startTime = previous.startTime
        task.endTime = previous.endTime
        task.startMinutes = previous.startMinutes
        task.endMinutes = previous.endMinutes
        TASKS.notice = writeErrorText(result)
      } else if (typeof result.after === 'string') {
        task.raw = result.after
        TASKS.notice = ''
      }
      loadTasks(true)
    }).catch(function () {
      TASKS.busy = false
      task.startTime = previous.startTime
      task.endTime = previous.endTime
      task.startMinutes = previous.startMinutes
      task.endMinutes = previous.endMinutes
      TASKS.notice = '写回失败：连不上 host'
      render(0)
    })
  }

  function createNoteForSelected() {
    if (!TASKS.caps.create || TASKS.busy) return
    TASKS.busy = true
    TASKS.notice = ''
    renderTasks()
    var url = '/dsh-calendar/notes/create' + rootQuery()
    var request
    try {
      request = fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-dsh-calendar': 'write' },
        body: JSON.stringify({ date: state.selected })
      })
    } catch (error) {
      TASKS.busy = false
      TASKS.notice = '新建失败：连不上 host'
      renderTasks()
      return
    }
    request.then(function (response) {
      return response.json().catch(function () { return null })
