    var scheduled = sortScheduled(all.filter(hasTime))
    var unscheduled = all.filter(function (task) { return !hasTime(task) })
    var progress = dayProgress(all)

    els.tasksTitle.textContent = formatDayTitle(state.selected, all.length, todayKey)
    els.tasksRefresh.hidden = TASKS.error !== null

    els.progress.hidden = all.length === 0
    els.progressFill.style.width = progress.pct + '%'
    els.progressText.textContent = progress.done + '/' + progress.total + ' 完成' +
      (progress.scheduled > 0 ? ' · ' + progress.scheduled + ' 个已排时间' : '')

    renderTimeline(scheduled, todayKey)

    els.taskList.textContent = ''
    if (unscheduled.length > 0 && scheduled.length > 0) {
      var groupTitle = document.createElement('li')
      groupTitle.className = 'cal-group-title'
      groupTitle.textContent = '未安排'
