    for (var i = 0; i < unscheduled.length; i++) els.taskList.appendChild(taskRow(unscheduled[i], todayKey, false))

    els.tasksEmpty.hidden = all.length > 0
    if (all.length === 0) {
      els.tasksEmpty.textContent = TASKS.error === 'unreachable'
        ? '（未连接 DSH：打开单文件页时读不到笔记库）'
