  }

  function renderTimeline(scheduled, todayKey) {
    var planner = TASKS.planner || {}
    var isToday = state.selected === todayKey
    var now = isToday && planner.showNow !== false ? (new Date().getHours() * 60 + new Date().getMinutes()) : null
    var built = buildTimeline(scheduled, {
      nowMinutes: now,
      defaultDurationMinutes: planner.defaultDurationMinutes
    })

    els.timeline.hidden = built.rows.length === 0
    els.timeline.textContent = ''
    for (var i = 0; i < built.rows.length; i++) {
      var row = built.rows[i]
      if (row.type === 'gap') {
        var gap = document.createElement('div')
        gap.className = 'cal-gap'
        var gapLabel = document.createElement('span')
        gapLabel.className = 'cal-gap-label'
        gapLabel.textContent = row.label
        var gapText = document.createElement('span')
        gapText.className = 'cal-gap-text'
        gapText.textContent = '⋯ ' + (row.to - row.from) + ' 小时无安排'
        gap.appendChild(gapLabel)
        gap.appendChild(gapText)
        els.timeline.appendChild(gap)
        continue
      }

      var hour = document.createElement('div')
      hour.className = 'cal-hour' + (row.tasks.length === 0 ? ' is-empty' : '')
      var label = document.createElement('span')
      label.className = 'cal-hour-label'
      label.textContent = row.label
      var body = document.createElement('div')
      body.className = 'cal-hour-body'
      for (var j = 0; j < row.tasks.length; j++) body.appendChild(taskRow(row.tasks[j], todayKey, true))
      hour.appendChild(label)
      hour.appendChild(body)

      if (row.nowOffsetPct !== undefined) {
        var needle = document.createElement('div')
        needle.className = 'cal-now'
        needle.style.top = 'calc(3px + (100% - 8px) * ' + (row.nowOffsetPct / 100).toFixed(3) + ')'
        var nowLabel = document.createElement('span')
        nowLabel.className = 'cal-now-label'
        nowLabel.textContent = '现在'
        needle.appendChild(nowLabel)
        hour.appendChild(needle)
