    }

    var glyph = document.createElement('button')
    glyph.type = 'button'
    glyph.className = 'cal-task-state cal-rippleable'
    glyph.textContent = STATE_GLYPH[task.state] || '○'
    if (TASKS.caps.write) {
      glyph.title = task.state === 'done' ? '标记为未完成（写回笔记）' : '标记为完成（写回笔记）'
